// The per-level curriculum documents (docs/academy-curriculum/<level>.md, generated by scripts/academy-curriculum-docs.ts) are current:
// each lists every Season with its big question and eight chapters. Failing here means: run `npx tsx scripts/academy-curriculum-docs.ts`.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { ACADEMY_SEASONS, PA1_SEASONS } from '../index';
import { PRE_A1_ARCS } from '../arcs';

const doc = (f: string) => readFileSync(`docs/academy-curriculum/${f}.md`, 'utf8');

describe('per-level curriculum documents are current', () => {
  for (const level of ['A1', 'A2', 'B1', 'B2', 'C1']) {
    it(`${level}: every Season, its big question and all eight chapter titles are in the document`, () => {
      const text = doc(level.toLowerCase());
      for (const s of ACADEMY_SEASONS.filter((x) => x.level === level)) {
        expect(text, `${s.id} heading`).toContain(`### ${s.id} ${s.title}`);
        expect(text, `${s.id} big question`).toContain(`**Big question:** ${s.essentialQuestion}`);
        for (const c of s.chapters!) expect(text, `${s.id} ${c.title}`).toContain(`**${c.title}**`);
      }
    });
  }
  it('Pre-A1: every Season and its chapters are in the document', () => {
    const text = doc('pre-a1');
    for (const s of PA1_SEASONS) {
      expect(text).toContain(s.id);
      for (const c of PRE_A1_ARCS[s.id].chapters) expect(text).toContain(`**${c.title}**`);
    }
  });
});
